import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for {@link Line#revert()}.
 */
public class Line_revert_TriageGen1Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testRevertWithStandardLine() {
        // Setup: Line through (1, 2, 3) with direction (1, 0, 0)
        Vector3D origin = new Vector3D(1.0, 2.0, 3.0);
        Vector3D direction = new Vector3D(1.0, 0.0, 0.0);
        Line line = new Line(origin, origin.add(direction));

        // Execute
        Line reverted = line.revert();

        // Verify
        // The logic is: new Line(zero, zero.subtract(direction))
        // Expected origin of reverted: (0, 0, 0)
        // Expected direction of reverted: -direction = (-1, 0, 0)
        assertNotNull(reverted);

        Vector3D expectedOrigin = Vector3D.ZERO;
        Vector3D expectedDir = direction.negate();

        // Since Line is defined by origin and direction, we check properties
        // The new origin should be ZERO
        // The new direction should be -originalDirection
        // Note: In Apache Commons Math, Line(p1, p2) sets p1 as origin and (p2-p1) as direction
        // The method implementation uses: new Line(zero, zero.subtract(direction))
        // So origin is (0,0,0) and direction is (0,0,0) - direction = -direction.

        assertEquals("Reverted origin should be zero", expectedOrigin, reverted.getOrigin());
        assertEquals("Reverted direction should be negated", expectedDir, reverted.getDirection());
    }

    @Test
    public void testRevertWithNegativeDirection() {
        // Setup: Line with direction (-1, -2, -3)
        Vector3D origin = new Vector3D(5.0, 5.0, 5.0);
        Vector3D direction = new Vector3D(-1.0, -2.0, -3.0);
        Line line = new Line(origin, origin.add(direction));

        // Execute
        Line reverted = line.revert();

        // Verify
        Vector3D expectedOrigin = Vector3D.ZERO;
        Vector3D expectedDir = direction.negate(); // (1, 2, 3)

        assertEquals(expectedOrigin, reverted.getOrigin());
        assertEquals(expectedDir, reverted.getDirection());
    }

    @Test
    public void testRevertWithZeroDirectionException() {
        // Note: Line constructor throws MathIllegalArgumentException if direction is zero.
        // However, the revert() method relies on an existing Line object.
        // If the original line was valid, its direction is non-zero.
        // We test if revert() maintains the mathematical properties.

        Vector3D origin = new Vector3D(0, 0, 0);
        Vector3D direction = new Vector3D(0, 1, 0);
        Line line = new Line(origin, origin.add(direction));

        Line reverted = line.revert();

        assertEquals(Vector3D.ZERO, reverted.getOrigin());
        assertEquals(new Vector3D(0, -1, 0), reverted.getDirection());
    }
}
